import{_ as o,o as u,c as q,ai as p}from"./chunks/framework.scx6l_IK.js";const i=JSON.parse('{"title":"金刚经3分-愿行合一","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经3分-愿行合一.md","filePath":"60-原文段落/金刚经3分-愿行合一.md","lastUpdated":1778155802000}'),e={name:"60-原文段落/金刚经3分-愿行合一.md"};function a(r,t,_,s,n,c){return u(),q("div",null,[...t[0]||(t[0]=[p('<h1 id="金刚经3分-愿行合一" tabindex="-1">金刚经3分-愿行合一 <a class="header-anchor" href="#金刚经3分-愿行合一" aria-label="Permalink to &quot;金刚经3分-愿行合一&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/3了空居士讲《金刚经》-第三分大乘正宗分20160916">3了空居士讲《金刚经》-第三分大乘正宗分20160916</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【答疑】</strong></p><p><strong>2.问：</strong>&quot;我皆令入无余涅槃而灭度之&quot;，这是从那个&quot;初发心的菩萨&quot;到&quot;菩萨&quot;到&quot;摩诃萨&quot;这样子的一个大菩萨，都是...</p><p>**了空居士：**都要发这个愿啊，都要发这个愿，都要希望一切众生都能够入&quot;无余涅槃&quot;，要发这个愿。&quot;我皆令入&quot;，这个时候你不要以为你能够一厢情愿地将它们进入了啊，不是的。因为众生毕竟是有他的主观能动性啊，有他的业力或者是愿力啊。比如说，我也希望所有的同修都能&quot;入无余涅槃而灭度之&quot;，那么我这个愿是这么发啊，那么我要落到实处去，我要天天为大家答疑解惑，怎么带大家怎么正道的修行，每天都要落实到这个具体的行为上去。先发个愿，然后要这么做，然后这么做之后，你发现&quot;唉呀，这位同修，哇，他也开悟了，很好&quot;，那么我们就不要执着：&quot;唉呀，这个就是我帮助他的&quot;，&quot;唉呀，这个是我帮助他的，他也没有感谢我&quot;，或者是&quot;他怎么也是那么平平常常的啊，没有特别的高兴啊&quot;，你就要觉得我能够令&quot;众生入无余涅槃&quot;这个是正常的事情，没有进去的反而就是我要继续去努力，是这个意思。</p><p>**主持：**那对于这个初发心的菩萨，就像我们这些刚刚开始学习的，那么我们自己离这个涅槃还远着呢，那怎么来帮助这个众生？</p><p>**了空居士：**也许你们说，唉呀，我自己都没有开悟，那怎么能够帮助众生啊？就是其实说&quot;入无余涅槃&quot;就是大彻大悟吧，可以说，如果从最标准上来说是大彻大悟。《楞严经》阿难有请教释迦牟尼佛，&quot;自未得度先度人者，菩萨发心，自觉已圆能觉他者，如来应世&quot;。你可能说&quot;唉呀，我都没有大彻大悟我怎么帮助众生啊？&quot;</p><p>我问你们：大彻大悟悟到了什么？</p><p>哈哈，你们说大彻大悟就明心见性。</p><p>那明心见性明了什么心？又见了什么性了？</p><p>哈哈，你说唉呀，那&quot;不思善不思恶，返照汝边&quot;</p><p>没错没错，对了。</p><p>你说那佛祖自己怎么说的？</p><p>&quot;知见无见，斯即涅槃，无漏真净&quot;啊。</p><p>那这就明白啦，我们自己要入无余涅槃，其实很简单，就是&quot;知见无见&quot;啦，不要带着任何成见去看问题和看自己啊，这就是六祖对惠明说&quot;不思善不思恶，返照汝边&quot;啊。你们明白了，你们现在就是&quot;无余涅槃&quot;了，是不是啊？</p><p>那么你说：唉呀就这么简单吗？</p><p>我说不简单啊，你过后是不是还是能够&quot;入无余涅槃&quot;，怎么看啊，你们知道吗？就是以后我们要讲的《金刚经》的《净心行善分》&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提&quot;。&quot;阿耨多罗三藐三菩提&quot;是印度语，翻译成现在的话就是&quot;无上正等正觉&quot;，那就是&quot;究竟涅槃&quot;，你们知不知道？&quot;究竟涅槃&quot;。那么你们要大彻大悟太简单了，不要带着任何成见，&quot;以无我无人无众生无寿者修一切善法&quot;，你们就达到了这个标准了。那你说那这样我就跟诸佛一样了？不是，你们要历境炼心，要处处能够使你都能够达到这个标准，那你就大彻大悟啦，跟诸佛如来一致啦，是不是啊？</p>',18)])])}const l=o(e,[["render",a]]);export{i as __pageData,l as default};
